from pathlib import Path
import re, json
root=Path('/mnt/data/work')

# Shared app.js: add referral generator and submission normalization.
p=root/'app.js'; s=p.read_text()
s=s.replace('  data.withdrawals = Array.isArray(data.withdrawals) ? data.withdrawals : [];\n', '  data.withdrawals = Array.isArray(data.withdrawals) ? data.withdrawals : [];\n  data.paymentSubmissions = Array.isArray(data.paymentSubmissions) ? data.paymentSubmissions : [];\n')
insert='''\nfunction generateUniqueReferralCode(users = []) {\n  const used = new Set((users || []).map(u => String(u.referralCode || '').trim().toUpperCase()).filter(Boolean));\n  let code = '';\n  do {\n    const seed = Math.random().toString(36).slice(2, 8).toUpperCase();\n    code = 'GF-' + seed;\n  } while (used.has(code));\n  return code;\n}\n\nfunction makeCustomerId(users = []) {\n  const used = new Set((users || []).map(u => String(u.id || '').trim().toUpperCase()).filter(Boolean));\n  let id = '';\n  do {\n    id = 'GFU-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();\n  } while (used.has(id));\n  return id;\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));\n}\n'''
s=s.replace('\nfunction getLoggedUser() {', insert+'\nfunction getLoggedUser() {')
p.write_text(s)

# Signup: guaranteed unique code and id.
p=root/'signup.html'; s=p.read_text()
s=s.replace("const code='GF'+Math.random().toString(36).slice(2,8).toUpperCase();const newUser={id:'USR'+Date.now(),fullName,email,password,referralCode:code", "const code=generateUniqueReferralCode(data.users);const customerId=makeCustomerId(data.users);const newUser={id:customerId,fullName,email,password,referralCode:code")
p.write_text(s)

# Replace product page with responsive cards + purchase modal + upload camera/gallery.
product='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f0c06"><title>Gold Fortune — Products</title><link rel="icon" href="icon-2.png"><link rel="manifest" href="manifest.json"><link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700&family=DM+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet"><style>
:root{--bg:#0f0c06;--card:#1c1710;--border:#4a3c24;--gold:#e8c547;--gold2:#ffc52e;--text:#f5eedc;--muted:#a79778;--green:#25c77a}*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}body{margin:0;background:radial-gradient(900px 400px at 50% -100px,rgba(232,197,71,.12),transparent 70%),var(--bg);color:var(--text);font-family:DM Sans,system-ui,sans-serif}.wrap{width:min(1180px,100%);margin:auto;padding:24px 18px 50px}.top{display:flex;align-items:center;gap:14px;margin:8px 0 26px}.back{width:44px;height:44px;display:grid;place-items:center;border:1px solid var(--border);border-radius:13px;color:var(--gold);text-decoration:none;font-size:30px}.top h1{font:700 clamp(1.7rem,4vw,2.2rem)/1.1 'Playfair Display',serif;margin:0}.hero{padding:28px;border:1px solid rgba(232,197,71,.3);border-radius:26px;background:linear-gradient(145deg,#292116,#17120b);margin-bottom:24px}.eyebrow{color:var(--gold);letter-spacing:2px;font-size:.72rem;text-transform:uppercase}.hero h2{font:700 clamp(1.7rem,4vw,2.3rem)/1.1 'Playfair Display',serif;margin:8px 0}.hero p{color:var(--muted);line-height:1.65;margin:0}.plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.plan{padding:24px;border-radius:24px;background:linear-gradient(145deg,#252016,#19140d);border:1px solid rgba(232,197,71,.3);box-shadow:0 16px 50px rgba(0,0,0,.2)}.plan-head{display:flex;align-items:center;gap:10px;margin-bottom:14px}.star{font-size:28px;color:var(--gold)}.badge{font-size:23px}.name{font:700 1.45rem 'Playfair Display',serif}.desc{color:var(--muted);line-height:1.5;min-height:48px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.label{font-size:.8rem;color:var(--muted)}.price{font:700 1.35rem 'Playfair Display',serif;margin-top:4px}.profit{color:var(--gold)}button,.btn{font:inherit}.btn{width:100%;min-height:52px;border-radius:15px;border:1px solid var(--gold);cursor:pointer;font-weight:800;background:linear-gradient(180deg,#ffc936,#e9ad1f);color:#171207}.btn.outline{background:transparent;color:var(--gold);margin-top:10px}.empty{padding:30px;text-align:center;color:var(--muted)}.modal-bg{position:fixed;inset:0;background:rgba(0,0,0,.78);display:none;align-items:flex-end;justify-content:center;padding:14px;z-index:20}.modal-bg.show{display:flex}.modal{width:min(560px,100%);max-height:92vh;overflow:auto;background:#1d1710;border:1px solid rgba(232,197,71,.35);border-radius:24px;padding:24px}.modal h3{font:700 1.6rem 'Playfair Display',serif;color:var(--gold);margin:0 0 8px}.muted{color:var(--muted);line-height:1.55}..bank{background:#30291f;border-radius:15px;padding:14px;margin:14px 0}.row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid rgba(232,197,71,.12)}.row:last-child{border-bottom:0}.row span:first-child{color:var(--muted)}.row span:last-child{font-weight:700;text-align:right;word-break:break-word}.upload{border:1px dashed rgba(232,197,71,.5);border-radius:16px;padding:18px;text-align:center;margin:16px 0;background:rgba(232,197,71,.04)}.upload input{display:none}.preview{display:none;width:100%;max-height:260px;object-fit:contain;border-radius:12px;margin-top:12px}.small{font-size:.78rem;color:var(--muted)}.actions{display:flex;gap:10px}.actions .btn{flex:1}@media(max-width:900px){.plans{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.wrap{padding:18px 14px 42px}.plans{grid-template-columns:1fr}.plan{padding:22px}.actions{flex-direction:column}.modal{border-radius:22px 22px 14px 14px}}
</style></head><body><main class="wrap"><div class="top"><a class="back" href="dashboard.html">‹</a><h1>Products</h1></div><section class="hero"><div class="eyebrow">Gold Fortune</div><h2>Choose your package</h2><p>Each package is displayed with its investment amount and stated return. Select <b>Buy Product</b> to view the payment details and submit a payment proof.</p></section><section id="plans" class="plans"><div class="empty">Loading products…</div></section><a class="btn outline" href="dashboard.html" style="display:flex;align-items:center;justify-content:center;text-decoration:none;margin-top:20px">Return to Dashboard</a></main><div class="modal-bg" id="buyModal"><div class="modal"><h3 id="buyTitle">Buy Product</h3><p class="muted" id="buyDesc"></p><div class="bank" id="buyBank"></div><div class="upload"><b>Upload payment proof</b><p class="small">Choose a photo from your gallery or use your camera. The submitted image will be visible to the administrator.</p><label class="btn" for="proofInput">📷 Choose photo / Camera</label><input id="proofInput" type="file" accept="image/*" capture="environment"><img id="proofPreview" class="preview" alt="Payment proof preview"></div><div class="actions"><button class="btn outline" onclick="closeBuy()">Cancel</button><button class="btn" id="submitProof">Submit</button></div><p id="proofMsg" class="small"></p></div></div><script src="app.js"></script><script>
let GF_DATA=null,GF_PRODUCTS=[];let selectedProduct=null;const esc=window.escapeHtml||((x)=>String(x??''));
function money(n){return '₦'+Number(n||0).toLocaleString('en-NG')}
async function load(){try{GF_DATA=await fetchBin();GF_PRODUCTS=GF_DATA.products||[];const box=document.getElementById('plans');box.innerHTML=GF_PRODUCTS.length?GF_PRODUCTS.map((p,i)=>`<article class="plan"><div class="plan-head"><span class="star">☆</span><span class="badge">${['🥉','🥈','🥇','💎','👑'][i%5]}</span><span class="name">${esc(p.name||'Plan')}</span></div><div class="desc">${esc(p.desc||'')}</div><div class="meta"><div><div class="label">Investment</div><div class="price">${money(p.price)}</div></div><div><div class="label">Profit</div><div class="price profit">${money(p.profit)}</div></div></div><button class="btn" onclick="openBuy('${String(p.id||'').replace(/'/g,"\\'")}')">▣ &nbsp; Buy Product</button><button class="btn outline" onclick="openBuy('${String(p.id||'').replace(/'/g,"\\'")}')">🎁 &nbsp; Verify &amp; Claim Product</button></article>`).join(''):'<div class="empty">No products available</div>';}catch(e){document.getElementById('plans').innerHTML='<div class="empty">Unable to load products.</div>';}}
function openBuy(id){selectedProduct=GF_PRODUCTS.find(p=>String(p.id)===String(id));if(!selectedProduct)return;const s=GF_DATA.settings||{};document.getElementById('buyTitle').textContent='Buy '+(selectedProduct.name||'Product');document.getElementById('buyDesc').textContent=selectedProduct.desc||'Review the payment details below.';document.getElementById('buyBank').innerHTML=`<div class="row"><span>Bank name</span><span>${esc(s.bankName||'—')}</span></div><div class="row"><span>Account name</span><span>${esc(s.accountName||'—')}</span></div><div class="row"><span>Account number</span><span>${esc(s.bankAccount||'—')}</span></div><div class="row"><span>Amount</span><span>${money(selectedProduct.price)}</span></div>`;document.getElementById('proofInput').value='';document.getElementById('proofPreview').style.display='none';document.getElementById('proofMsg').textContent='';document.getElementById('buyModal').classList.add('show')}
function closeBuy(){document.getElementById('buyModal').classList.remove('show')}
document.getElementById('proofInput').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/'))return;const r=new FileReader();r.onload=()=>{const img=document.getElementById('proofPreview');img.src=r.result;img.style.display='block'};r.readAsDataURL(f)});
function compressImage(file,max=1200,quality=.72){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,max/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',quality))};im.onerror=reject;im.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
document.getElementById('submitProof').onclick=async()=>{const msg=document.getElementById('proofMsg'),file=document.getElementById('proofInput').files?.[0],u=getLoggedUser();if(!u||!selectedProduct){msg.textContent='Please sign in again.';return}if(!file){msg.textContent='Please choose a payment proof image.';return}const btn=document.getElementById('submitProof');btn.disabled=true;btn.textContent='Submitting…';try{const d=await fetchBin();d.paymentSubmissions=d.paymentSubmissions||[];const imageData=await compressImage(file);d.paymentSubmissions.unshift({id:'PAY-'+Date.now()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),userId:u.id||'',email:u.email,fullName:u.fullName||'',productId:selectedProduct.id,productName:selectedProduct.name||'',amount:Number(selectedProduct.price||0),fileName:file.name,imageData,status:'pending',date:new Date().toISOString()});await saveBin(d);msg.textContent='Submitted successfully. The administrator can now review the uploaded proof.';setTimeout(closeBuy,900)}catch(e){console.error(e);msg.textContent='Submission failed. Please try again.'}finally{btn.disabled=false;btn.textContent='Submit'}};
load();if(!getLoggedUser())location.replace('login.html');
</script></body></html>'''
(root/'product.html').write_text(product)

